draw:
var g = 9.8;
var m = p.mass, F = p.push;
var N = m * g;
var fmax = p.mus * N;
var fk = Math.min(p.muk, p.mus) * N;
var moving = F > fmax;
var a = moving ? (F - fk) / m : 0;
var f = moving ? fk : F;

var floorY = H - 52;
var bw = Math.max(46, W * 0.14), bh = bw * 0.72;
var cycle = 2.6;
var tt = t % cycle;
var travel = moving ? 0.5 * a * tt * tt * 6 : 0;
var maxTravel = W * 0.32;
if (travel > maxTravel) travel = maxTravel;
var bx = W * 0.28 + travel;

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, floorY); ctx.lineTo(W, floorY); ctx.stroke();
for (var i = 0; i < W; i += 12) {
  ctx.beginPath(); ctx.moveTo(i, floorY); ctx.lineTo(i - 7, floorY + 7); ctx.stroke();
}

ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.25;
ctx.fillRect(bx - bw / 2, floorY - bh, bw, bh);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.strokeRect(bx - bw / 2, floorY - bh, bw, bh);

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 8 * Math.cos(ang - 0.4), y2 - 8 * Math.sin(ang - 0.4));
  ctx.lineTo(x2 - 8 * Math.cos(ang + 0.4), y2 - 8 * Math.sin(ang + 0.4));
  ctx.closePath(); ctx.fill();
}

var scale = (W * 0.20) / 80;
var midY = floorY - bh / 2;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

if (F > 0.5) {
  arrow(bx - bw / 2 - F * scale, midY, bx - bw / 2, midY, C.accent);
  ctx.fillStyle = C.accent;
  ctx.textAlign = "right";
  ctx.fillText("F = " + F.toFixed(0) + " N", bx - bw / 2 - F * scale - 6, midY - 6);
}
if (f > 0.5) {
  arrow(bx + bw / 2 + f * scale, floorY - 6, bx + bw / 2, floorY - 6, C.figure);
  ctx.fillStyle = C.figure;
  ctx.textAlign = "left";
  ctx.fillText("friction " + f.toFixed(1) + " N", bx + bw / 2 + 6, floorY + 18);
}

ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText("budget  mu_s N = " + fmax.toFixed(1) + " N", 10, 18);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
var barX = 10, barY = 26, barW = W - 20, barH = 10;
ctx.strokeRect(barX, barY, barW, barH);
var frac = Math.min(1, F / fmax);
ctx.fillStyle = moving ? C.accent : C.figure;
ctx.globalAlpha = 0.55;
ctx.fillRect(barX + 1, barY + 1, (barW - 2) * frac, barH - 2);
ctx.globalAlpha = 1;

if (moving) {
  out.note = "sliding: friction locked at mu_k N = " + fk.toFixed(1) + " N, a = " + a.toFixed(2) + " m/s^2";
} else {
  out.note = "at rest: friction = " + F.toFixed(1) + " N, which is " + (100 * frac).toFixed(0) + "% of the " + fmax.toFixed(1) + " N budget";
}

var g = 9.8;
var th = p.angle * Math.PI / 180;
var demand = Math.sin(th);
var budget = p.mus * Math.cos(th);
var slips = demand > budget;
var a = slips ? g * (Math.sin(th) - Math.min(p.muk, p.mus) * Math.cos(th)) : 0;
if (a < 0) a = 0;

var pad = 26;
var ox = pad, oy = H - pad;
var len = W - 2 * pad - 10;
var tipY = oy - len * Math.tan(th);
if (tipY < 30) { len = (oy - 30) / Math.tan(th); tipY = 30; }

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(ox, oy); ctx.lineTo(ox + len, oy); ctx.lineTo(ox + len, tipY); ctx.closePath();
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText(p.angle.toFixed(0) + " deg", ox + 22, oy - 6);

var cycle = 2.4;
var tt = t % cycle;
var s = slips ? 0.5 * a * tt * tt * 3 : 0;
var maxS = len * 0.7;
if (s > maxS) s = maxS;
var ux = -Math.cos(th), uy = Math.sin(th);
var startFrac = 0.72;
var bxs = ox + len - len * (1 - startFrac) - len * startFrac * 0.15;
var cx = ox + len * 0.80 + ux * s;
var cy = tipY + (oy - tipY) * 0.20 + uy * s;

var bw = 34, bh = 22;
ctx.save();
ctx.translate(cx, cy);
ctx.rotate(-th);
ctx.fillStyle = C.figure; ctx.globalAlpha = 0.25;
ctx.fillRect(-bw / 2, -bh, bw, bh);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.5;
ctx.strokeRect(-bw / 2, -bh, bw, bh);
ctx.restore();

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 7 * Math.cos(ang - 0.4), y2 - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x2 - 7 * Math.cos(ang + 0.4), y2 - 7 * Math.sin(ang + 0.4));
  ctx.closePath(); ctx.fill();
}

var mid = 34;
var hx = cx - Math.cos(th) * 0, hy = cy - Math.sin(th) * 0;
var cxm = cx + Math.sin(th) * (bh / 2) * 0 - Math.sin(th) * 11;
var cym = cy - Math.cos(th) * 11;
arrow(cxm, cym, cxm + Math.cos(th) * demand * mid * 2, cym + Math.sin(th) * demand * mid * 2, C.accent);
var fdraw = slips ? Math.min(p.muk, p.mus) * Math.cos(th) : demand;
arrow(cxm, cym, cxm - Math.cos(th) * fdraw * mid * 2, cym - Math.sin(th) * fdraw * mid * 2, C.figure);

ctx.textAlign = "left";
ctx.fillStyle = C.accent;
ctx.fillText("mg sin", W * 0.46, H - 44);
ctx.fillStyle = C.figure;
ctx.fillText("friction", W * 0.46, H - 28);

ctx.fillStyle = C.ink;
ctx.fillText("tan = " + Math.tan(th).toFixed(3) + "   mu_s = " + p.mus.toFixed(2), 10, 16);

out.note = slips
  ? "slipping: tan(angle) = " + Math.tan(th).toFixed(3) + " exceeds mu_s = " + p.mus.toFixed(2) + ", a = " + a.toFixed(2) + " m/s^2"
  : "held: needs " + (demand * 100).toFixed(1) + "% of mg, budget is " + (budget * 100).toFixed(1) + "% of mg";

var th = p.angle * Math.PI / 180;
var cone = Math.atan(p.mus);

var ox = 34, oy = H - 34;
var len = W - 80;
var tipY = oy - len * Math.tan(th);
if (tipY < 40) { len = (oy - 40) / Math.tan(th); tipY = 40; }

ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(ox, oy); ctx.lineTo(ox + len, oy); ctx.lineTo(ox + len, tipY); ctx.closePath();
ctx.stroke();

var cx = ox + len * 0.52;
var cy = oy - (len * 0.48) * Math.tan(th);

ctx.save();
ctx.translate(cx, cy);
ctx.rotate(-th);
ctx.fillStyle = C.figure; ctx.globalAlpha = 0.22;
ctx.fillRect(-20, -26, 40, 26);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.5;
ctx.strokeRect(-20, -26, 40, 26);
ctx.restore();

var px = cx - Math.sin(th) * 13;
var py = cy - Math.cos(th) * 13;

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = wid || 2;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 8 * Math.cos(ang - 0.4), y2 - 8 * Math.sin(ang - 0.4));
  ctx.lineTo(x2 - 8 * Math.cos(ang + 0.4), y2 - 8 * Math.sin(ang + 0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

var L = 64;
arrow(px, py, px, py + L, C.ink);
ctx.fillStyle = C.ink;
ctx.fillText("mg", px + 6, py + L + 4);

var nx = Math.sin(th), ny = -Math.cos(th);
arrow(px, py, px + nx * L * Math.cos(th), py + ny * L * Math.cos(th), C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("N = mg cos", px + nx * L * Math.cos(th) + 4, py + ny * L * Math.cos(th) - 4);

var tx = -Math.cos(th), ty = -Math.sin(th);
arrow(px, py, px - tx * L * Math.sin(th), py - ty * L * Math.sin(th), C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("mg sin", px - tx * L * Math.sin(th) + 4, py - ty * L * Math.sin(th) + 14);

arrow(px, py, px + tx * L * Math.sin(th), py + ty * L * Math.sin(th), C.accent);
ctx.fillText("friction", px + tx * L * Math.sin(th) - 56, py + ty * L * Math.sin(th) - 6);

ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
var R = 78;
var base = Math.atan2(ny, nx);
ctx.beginPath();
ctx.moveTo(px, py);
ctx.lineTo(px + R * Math.cos(base - cone), py + R * Math.sin(base - cone));
ctx.stroke();
ctx.beginPath();
ctx.moveTo(px, py);
ctx.lineTo(px + R * Math.cos(base + cone), py + R * Math.sin(base + cone));
ctx.stroke();
ctx.beginPath();
ctx.arc(px, py, R, base - cone, base + cone);
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("friction cone, half angle " + (cone * 180 / Math.PI).toFixed(1) + " deg", 10, 16);
ctx.fillText("slope " + p.angle.toFixed(0) + " deg", 10, 32);

out.note = (Math.tan(th) <= p.mus)
  ? "mg points inside the cone: the surface can hold it (tan = " + Math.tan(th).toFixed(3) + " <= " + p.mus.toFixed(2) + ")"
  : "mg points outside the cone: no way to hold it (tan = " + Math.tan(th).toFixed(3) + " > " + p.mus.toFixed(2) + ")";

var g = 9.8;
var mu = p.muk, m = p.mass;
function T(a) { return mu * m * g / (Math.cos(a) + mu * Math.sin(a)); }
var best = Math.atan(mu);
var Tbest = T(best);
var th = p.angle * Math.PI / 180;
var Tnow = T(th);

var pad = 40;
var x0 = pad, x1 = W - 14;
var y0 = H - 34, y1 = 26;
var amax = 80 * Math.PI / 180;
var tmax = Math.max(T(0), T(amax)) * 1.12;

ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y0); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0, y1); ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("rope angle above horizontal (deg)", (x0 + x1) / 2, H - 12);
ctx.textAlign = "left";
ctx.fillText("tension (N)", x0 - 30, y1 - 10);

function PX(a) { return x0 + (a / amax) * (x1 - x0); }
function PY(v) { return y0 - (v / tmax) * (y0 - y1); }

ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var a = amax * i / 120;
  if (i === 0) ctx.moveTo(PX(a), PY(T(a))); else ctx.lineTo(PX(a), PY(T(a)));
}
ctx.stroke();

ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(PX(best), y0); ctx.lineTo(PX(best), PY(Tbest)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, PY(Tbest)); ctx.lineTo(PX(best), PY(Tbest)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(PX(th), PY(Tnow), 5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("min at arctan(mu) = " + (best * 180 / Math.PI).toFixed(1) + " deg", PX(best) + 6, PY(Tbest) - 8);
ctx.textAlign = "center";
ctx.fillText("0", x0, y0 + 16);
ctx.fillText("80", x1 - 6, y0 + 16);

out.note = "at " + p.angle.toFixed(0) + " deg you need " + Tnow.toFixed(1) + " N; the best angle " + (best * 180 / Math.PI).toFixed(1) + " deg needs " + Tbest.toFixed(1) + " N";
